	,sickBeats: null
	,beatHit: function() {
		funkin_backend_MusicBeatState.prototype.beatHit.call(this);
		if(!funkin_states_TitleState.closedState) {
			this.sickBeats++;
			this.scriptGroup.set("curBeat",this.sickBeats);
		}
		if(!(this.scriptGroup == null || this.scriptGroup.call("customMenu") != true) || this.scriptGroup.call("onBeatHit",[]) == funkin_scripting_ScriptConstants.STOP_FUNC) {
			return;
		}
		if(this.scriptGroup == null || this.scriptGroup.call("customMenu") != true) {
			if(this.logo != null) {
				this.logo.animation.play("bump",true);
			}
			if(!funkin_states_TitleState.closedState) {
				switch(this.sickBeats) {
				case 1:
					funkin_audio_FunkinSound.playMusic(funkin_FunkinAssets.getSound(funkin_Paths.findFileWithExts("music/" + "freakyMenu",funkin_Paths.AUDIO_EXTENSIONS,null,funkin_PathsTestMode.NORMAL)),0);
					if(funkin_data_ClientPrefs.finaleState != funkin_data_FinaleState.ACTIVE) {
						var _this = flixel_FlxG.sound.music;
						if(_this._channel == null) {
							_this.play();
						}
						if(_this.fadeTween != null) {
							_this.fadeTween.cancel();
						}
						_this.fadeTween = flixel_tweens_FlxTween.num(0,0.7,4,{ onComplete : null},$bind(_this,_this.volumeTween));
					}
					break;
				case 2:
					this.createCoolText(["MOTORFROG"]);
					break;
				case 4:
					this.addMoreText("presents");
					break;
				case 5:
					this.deleteCoolText();
					break;
				case 6:
					this.createCoolText(["This is a mod to"],-60);
					break;
				case 8:
					this.addMoreText("This game right below lol",-60);
					if(this.ngSpr != null) {
						this.ngSpr.set_visible(true);
					}
					break;
				case 9:
					this.deleteCoolText();
					if(this.ngSpr != null) {
						this.ngSpr.set_visible(false);
					}
					break;
				case 10:
					if(this.randomIntroText[0] != null) {
						this.createCoolText([this.randomIntroText[0]]);
					}
					break;
				case 12:
					if(this.randomIntroText[1] != null) {
						this.addMoreText(this.randomIntroText[1]);
					}
					break;
				case 13:
					this.deleteCoolText();
					break;
				case 14:
					if(this.introEndingText[0] != null) {
						this.addMoreText(this.introEndingText[0]);
					}
					break;
				case 15:
					if(this.introEndingText[1] != null) {
						this.addMoreText(this.introEndingText[1]);
					}
					break;
				case 16:
					if(this.introEndingText[2] != null) {
						this.addMoreText(this.introEndingText[2]);
					}
					break;
				case 17:
					this.skipIntro();
					break;
				}
			}
		}
	}
	,skipIntro: function() {
		if(this.scriptGroup.call("onSkipIntro",[]) != funkin_scripting_ScriptConstants.STOP_FUNC && !this.skippedIntro) {
			var tmp = this.ngSpr;
			if(tmp != null) {
				tmp.kill();
			}
			var tmp = this.textGroup;
			if(tmp != null) {
				tmp.kill();
			}
			if(this.starFG != null && this.starBG != null) {
				this.starBG.set_alpha(1);
				this.starFG.set_alpha(1);
			}
			if(this.logo != null) {
				this.logo.set_alpha(1);
			}
			if(this.titleText != null) {
				this.titleText.set_alpha(1);
			}
			flixel_FlxG.camera.flash(-1,4);
			this.skippedIntro = true;
		}
	}
