				this.inPostDialogue = false;
				this.cameraUnlocked = true;
				flixel_tweens_FlxTween.tween(this.dlgOverlay,{ alpha : 0},0.25,{ ease : flixel_tweens_FlxEase.quadOut, onComplete : function(_) {
					_gthis.dlgOverlay.set_visible(false);
				}});
				flixel_tweens_FlxTween.tween(this.dlgText,{ alpha : 0},0.2,{ ease : flixel_tweens_FlxEase.quadOut});
				flixel_tweens_FlxTween.tween(this.dlgYesBro,{ alpha : 0},0.2);
