	,formatArabicDialogueText: function(source) {
		if(!this.rtlMode || source == null || source.length < 1 || this.rtlWrapMeasure == null) {
			return source;
		}
		var wrappedLines = [];
		var _g = 0;
		var _g1 = source.split("\n");
		while(_g < _g1.length) {
			var paragraph = _g1[_g];
			++_g;
			if(StringTools.trim(paragraph).length < 1) {
				wrappedLines.push("");
				continue;
			}
			var words = paragraph.split(" ");
			var currentLine = "";
			var _g2 = 0;
			var _g3 = words.length;
			while(_g2 < _g3) {
				var word = words[words.length - 1 - _g2++];
				var candidate = currentLine.length > 0 ? word + " " + currentLine : word;
				this.rtlWrapMeasure.set_text(candidate);
				if(currentLine.length > 0 && this.rtlWrapMeasure.textField.get_numLines() > 1) {
					wrappedLines.unshift(currentLine);
					currentLine = word;
				} else {
					currentLine = candidate;
				}
			}
			wrappedLines.unshift(currentLine);
		}
		this.rtlWrapMeasure.set_text("");
		return wrappedLines.join("\n");
	}
