	,closeSubState: function() {
		if(this.paused) {
			if(!this.startingSong) {
				this.audio.set_time(funkin_backend_Conductor.songPosition);
				this.audio.play();
			}
			flixel_util_FlxTimer.globalManager.forEach(function(i) {
				if(!i.finished) {
					i.active = true;
				}
			});
			flixel_tweens_FlxTween.globalManager.forEach(function(i) {
				if(!i.finished) {
					i.set_active(true);
				}
			});
			funkin_video_FunkinVideoSprite.forEachAlive(function(video) {
				if(video.tiedToGame) {
					video.resume();
				}
			});
			this.paused = false;
			this.set_playbackRate(this.playbackRate);
			this.scripts.call("onResume",[]);
			var showTime = this.startTimer != null && this.startTimer.finished;
			if(showTime == null) {
				showTime = false;
			}
		}
		this.scripts.call("onSubstateClose",[]);
		funkin_backend_MusicBeatState.prototype.closeSubState.call(this);
	}
