	,spawnNote: function(note) {
		note.postRecycle();
		var tmp;
		var v = this.callNoteTypeScript(note.noteType,"spawnNote",[note]);
		if(!(v == funkin_scripting__$ScriptConstants_ScriptDispatch.Stop || v == funkin_scripting__$ScriptConstants_ScriptDispatch.Cancel)) {
			var v = this.scripts.call("onSpawnNote",[note],false,[note.noteType]);
			tmp = v == funkin_scripting__$ScriptConstants_ScriptDispatch.Stop || v == funkin_scripting__$ScriptConstants_ScriptDispatch.Cancel;
		} else {
			tmp = true;
		}
		if(tmp) {
			note.kill();
			return null;
		}
		var expectedPlayfield = this.getFieldFromID(note.lane);
		if(expectedPlayfield == null) {
			note.kill();
			return null;
		} else if(expectedPlayfield.autoPlayed && note.strumTime <= funkin_backend_Conductor.songPosition && !note.ignoreNote) {
			expectedPlayfield.onNoteHit.dispatch(note,expectedPlayfield);
			note.kill();
			return null;
		} else if(!expectedPlayfield.autoPlayed && (note.strumTime < funkin_backend_Conductor.songPosition - funkin_backend_Conductor.safeZoneOffset && !note.wasGoodHit) && !note.ignoreNote && !note.canMiss && !this.endingSong) {
			expectedPlayfield.onNoteMiss.dispatch(note,expectedPlayfield);
			note.kill();
			return null;
		} else {
			expectedPlayfield.notes.push(note);
			note.player = expectedPlayfield.player;
			note.skin = expectedPlayfield._skin;
			note.set_texture(expectedPlayfield._skin.noteTexture);
			note.rgbEnabled = expectedPlayfield._skin.inEngineColoring;
			note.rgbGraphics.enabled = note.rgbEnabled;
			if(expectedPlayfield.hasChangedSkin) {
				note.updateColors();
			}
			var p = note.scale;
			var x = p.x;
			var y = p.y;
			if(y == null) {
				y = 0;
			}
			if(x == null) {
				x = 0;
			}
			note.baseScale.set(x,y);
			var _this = p;
			if(_this._weak) {
				_this.put();
			}
			note.updateHitbox();
			if(note.playField != expectedPlayfield || note.playField == null) {
				note.set_playField(expectedPlayfield);
			}
			note.strum = expectedPlayfield.members[note.noteData];
			this.notes.remove(note,true);
			this.notes.insert(0,note);
			note.spawned = true;
			var v = this.callNoteTypeScript(note.noteType,"postSpawnNote",[note]);
			if(!(v == funkin_scripting__$ScriptConstants_ScriptDispatch.Stop || v == funkin_scripting__$ScriptConstants_ScriptDispatch.Cancel)) {
				this.scripts.call("onSpawnNotePost",[note],false,[note.noteType]);
			}
			return note;
		}
	}
