	,checkEventNote: function() {
		while(this.eventNotes.length > 0) {
			if(funkin_backend_Conductor.songPosition < this.eventNotes[0].strumTime) {
				break;
			}
			var tmp = this.eventNotes[0].value1;
			var tmp1 = this.eventNotes[0].value2;
			this.triggerEventNote(this.eventNotes[0].event,tmp != null ? tmp : "",tmp1 != null ? tmp1 : "");
			this.eventNotes.shift();
		}
	}
	,changeCharacter: function(name,charType) {
		var prevChar = null;
		var newChar;
		switch(charType) {
		case 0:
			prevChar = this.boyfriend;
			newChar = this.boyfriend = this.boyfriendGroup.change(name);
			break;
		case 1:
			prevChar = this.dad;
			newChar = this.dad = this.dadGroup.change(name);
			break;
		case 2:
			prevChar = this.gf;
			(this.gf = this.gfGroup.change(name)).danceSpeed = prevChar.danceSpeed;
			newChar = this.gf;
			break;
		default:
			newChar = null;
		}
		var groupMembers = this.playFields.members;
		var _g__cursor = 0;
		var _g__length = groupMembers.length;
		while(true) {
			while(_g__cursor < _g__length && groupMembers[_g__cursor] == null) ++_g__cursor;
			if(!(_g__cursor < _g__length)) {
				break;
			}
			while(_g__cursor < _g__length && groupMembers[_g__cursor] == null) ++_g__cursor;
			var field = _g__cursor < _g__length ? groupMembers[_g__cursor++] : null;
			if(field.get_owner() == prevChar) {
				field.set_owner(newChar);
			}
		}
		this.callHUDFunc(function(hud) {
			hud.onCharacterChange();
		});
	}
